/// Find an installed skill by its exact name.
pub fn skill(name: &str) -> Option<&'static Skill> {
    SKILLS.iter().find(|s| s.name == name)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lookup_is_exact() {
        for entry in SKILLS {
            assert_eq!(skill(entry.name).map(|s| s.name), Some(entry.name));
        }
        assert!(skill("missing-skill").is_none());
    }
}
